use vstd::prelude::*;

verus! {

fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
    ensures
        result.len() == s.len()
    &&
        forall(|i: usize| i < s.len() ==>
            result[i].len() == i + 1
            &&
            forall(|j: usize| j <= i ==> result[i][j] == s[j])
        )
{
    let mut result: Vec<Vec<char>> = Vec::new();
    let mut prefix: Vec<char> = Vec::new();

    let mut i: usize = 0;
    while i < s.len()
        invariant
            i <= s.len(),
            result.len() == i,
            prefix.len() == i,
            // For all completed prefixes in result:
            forall(|k: usize| k < i ==>
                result[k].len() == k + 1
                &&
                forall(|j: usize| j <= k ==> result[k][j] == s[j])
            ),
            // prefix matches s[0..i]
            forall(|j: usize| j < i ==> prefix[j] == s[j]),
        decreases s.len() - i,
    {
        prefix.push(s[i]);
        // Clone the current prefix and push into result
        // Cloning prefix is necessary to satisfy ownership rules
        result.push(prefix.clone());

        i += 1;
    }

    result
}

}
